// plain-language reasons for a susceptibility feature and its value
const F = {
  slope: (v) => [`steep (${v.toFixed(0)}°)`, `급경사 (${v.toFixed(0)}°)`],
  steep30: (v) => [`${(v * 100).toFixed(0)}% of it is steeper than 30°`, `30° 이상 구간 ${(v * 100).toFixed(0)}%`],
  relief: (v) => [`large height difference (${v.toFixed(0)} m within 180 m)`, `큰 고도차 (180 m 내 ${v.toFixed(0)} m)`],
  relief450: (v) => [`large height difference (${v.toFixed(0)} m within 450 m)`, `큰 고도차 (450 m 내 ${v.toFixed(0)} m)`],
  curv: (v) => v > 0 ? ['hollow shape, where water gathers', '물이 모이는 오목한 지형'] : ['ridge shape', '능선형 지형'],
  tpi: (v) => v > 0 ? [`upper slope (${v.toFixed(0)} m above its surroundings)`, `상부 사면 (주변보다 ${v.toFixed(0)} m 높음)`] : [`lower slope (${(-v).toFixed(0)} m below its surroundings)`, `하부 사면 (주변보다 ${(-v).toFixed(0)} m 낮음)`],
  twi: (v) => [`wetness index ${v.toFixed(1)}`, `습윤 지수 ${v.toFixed(1)}`],
  dstream: (v) => [`${v.toFixed(0)} m from a stream`, `하천에서 ${v.toFixed(0)} m`],
  dem: (v) => [`elevation ${v.toFixed(0)} m`, `고도 ${v.toFixed(0)} m`],
  northness: (v) => v > 0 ? ['north-facing', '북향'] : ['south-facing', '남향'],
  eastness: (v) => v > 0 ? ['east-facing', '동향'] : ['west-facing', '서향'],
  dnbr: (v) => [`burn severity dNBR ${v.toFixed(2)}`, `산불 피해 강도 dNBR ${v.toFixed(2)}`],
  burn_frac: (v) => [`${(v * 100).toFixed(0)}% burned at moderate or high severity`, `${(v * 100).toFixed(0)}%가 중간 이상 피해`],
  burn_high: (v) => [`${(v * 100).toFixed(0)}% burned at high severity`, `${(v * 100).toFixed(0)}%가 심한 피해`],
  loss2025: (v) => [`${(v * 100).toFixed(0)}% tree cover lost in 2025`, `2025년 수목 손실 ${(v * 100).toFixed(0)}%`],
  loss_pre: (v) => [`${(v * 100).toFixed(0)}% tree cover lost before 2025`, `2025년 이전 수목 손실 ${(v * 100).toFixed(0)}%`],
  ndvi_pre: (v) => [`vegetation in June 2026: NDVI ${v.toFixed(2)}${v < 0.6 ? ' (sparse)' : ''}`, `2026년 6월 식생: NDVI ${v.toFixed(2)}${v < 0.6 ? ' (빈약)' : ''}`],
  ndvi_postfire: (v) => [`vegetation after the fire: NDVI ${v.toFixed(2)}`, `산불 직후 식생: NDVI ${v.toFixed(2)}`],
  treecover: (v) => [`tree cover ${v.toFixed(0)}% (2000)`, `수목 피복 ${v.toFixed(0)}% (2000년)`],
  lc_tree: (v) => [`${(v * 100).toFixed(0)}% forest`, `산림 ${(v * 100).toFixed(0)}%`],
  lc_shrub: (v) => [`${(v * 100).toFixed(0)}% shrub`, `관목 ${(v * 100).toFixed(0)}%`],
  lc_grass: (v) => [`${(v * 100).toFixed(0)}% grassland`, `초지 ${(v * 100).toFixed(0)}%`],
  lc_crop: (v) => [`${(v * 100).toFixed(0)}% cropland`, `농경지 ${(v * 100).toFixed(0)}%`],
  lc_bare: (v) => [`${(v * 100).toFixed(0)}% bare ground`, `나지 ${(v * 100).toFixed(0)}%`],
  rain_ante30: (v) => [`${v.toFixed(0)} mm of rain in the 30 days before the storm`, `폭우 전 30일 강수 ${v.toFixed(0)} mm`],
  rain_max1_pre: (v) => [`wettest day before the storm: ${v.toFixed(0)} mm`, `폭우 이전 일 최대 강수 ${v.toFixed(0)} mm`],
  rain_max3_pre: (v) => [`wettest 3 days before the storm: ${v.toFixed(0)} mm`, `폭우 이전 3일 최대 강수 ${v.toFixed(0)} mm`],
};
export const reason = (name, v, lang) => (F[name] ? F[name](v)[lang === 'ko' ? 1 : 0] : `${name} ${v.toFixed(2)}`);
export const compass = (deg, lang) => (lang === 'ko' ? ['북', '북동', '동', '남동', '남', '남서', '서', '북서'] : ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'])[Math.round(deg / 45) % 8];

// short everyday names for the model inputs (used in "How the AI works")
const FN = {
  slope: ['steepness', '경사'], steep30: ['very steep sections', '급경사 구간'], relief: ['height difference across the slope', '사면의 고도차'],
  curv: ['hollows where water gathers', '물이 모이는 오목한 지형'], tpi: ['position on the hill', '사면 위치'], twi: ['how wet the ground gets', '지면 습윤도'],
  dstream: ['distance to a stream', '하천까지 거리'], dem: ['elevation', '고도'], northness: ['north or south facing', '남북 방향'], eastness: ['east or west facing', '동서 방향'],
  dnbr: ['fire damage', '산불 피해'], burn_frac: ['share of the slope burned', '불탄 면적 비율'], burn_high: ['severely burned area', '심하게 탄 면적'],
  loss2025: ['trees lost in 2025', '2025년 수목 손실'], loss_pre: ['earlier tree loss', '이전 수목 손실'], ndvi_pre: ['vegetation before the storm', '폭우 전 식생'],
  ndvi_postfire: ['vegetation left after the fire', '산불 뒤 남은 식생'], treecover: ['original tree cover', '원래 수목 피복'],
  lc_tree: ['forest cover', '산림'], lc_shrub: ['shrub cover', '관목'], lc_grass: ['grassland', '초지'], lc_crop: ['cropland', '농경지'], lc_bare: ['bare ground', '나지'],
  rain_ante30: ['rain in the month before the storm', '폭우 전 한 달 강수'], rain_max1_pre: ['wettest day before the storm', '폭우 전 일 최대 강수'], rain_max3_pre: ['wettest 3 days before the storm', '폭우 전 3일 최대 강수'],
};
export const featName = (name, lang) => (FN[name] ? FN[name][lang === 'ko' ? 1 : 0] : name);
